{
  "implementation": "def solve(case):
    import json
    payload = case['payload']
    segments = payload['segments']
    budget = payload['budget']
    sum_min = sum(s['minimum'] for s in segments)
    sum_cap = sum(s['capacity'] for s in segments)
    if budget < sum_min or budget > sum_cap:
        return {'error': 'budget out of range'}
    alloc = {s['name']: s['minimum'] for s in segments}
    remaining = budget - sum_min
    order = [s['name'] for s in segments]
    while remaining > 0:
        best = None
        best_ratio = -1
        best_idx = -1
        for idx, s in enumerate(segments):
            name = s['name']
            if alloc[name] < s['capacity']:
                ratio = s['importance'] / (alloc[name] + 1)
                if ratio > best_ratio or (ratio == best_ratio and idx < best_idx):
                    best_ratio = ratio
                    best_idx = idx
                    best = name
        if best is None:
            break
        alloc[best] += 1
        remaining -= 1
    return {
        'allocations': alloc,
        'names': order,
        'total': budget
    }"
}
